import React, { useState, useEffect } from 'react';
import api from '../services/api';
import Calendar from '../components/Calendar';

const EMPTY_DISPO = {
  date_specifique: '',
  heure_debut: '09:00',
  heure_fin: '10:00',
  nb_max_etudiants: 1,
};

export default function Disponibilites() {
  const [dispos, setDispos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [newDispo, setNewDispo] = useState({ ...EMPTY_DISPO });
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    fetchDispos();
  }, []);

  const fetchDispos = async () => {
    try {
      const res = await api.get('/api/professeurs/me/disponibilites');
      setDispos(res.data ?? []);
    } catch (e) {
      console.error('Erreur chargement dispos:', e.response?.data);
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await api.post('/api/professeurs/me/disponibilites', {
        ...newDispo,
        nb_max_etudiants: parseInt(newDispo.nb_max_etudiants, 10),
      });
      setShowForm(false);
      // Réinitialise le formulaire pour éviter des envois en double
      setNewDispo({ ...EMPTY_DISPO });
      // await garantit que les données sont à jour avant le message
      await fetchDispos();
      alert('✅ Séance ajoutée !');
    } catch (e) {
      console.error('Détail erreur ajout:', e.response?.data);
      alert('Erreur lors de l\'ajout : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm('Supprimer ce créneau ?')) {
      try {
        await api.delete(`/api/professeurs/me/disponibilites/${id}`);
        // Mise à jour locale immédiate sans attendre le serveur
        setDispos(prev => prev.filter(d => d.id !== id));
      } catch (e) {
        console.error('Détail erreur suppression:', e.response?.data);
        alert('Erreur lors de la suppression : ' + (e.response?.data?.detail || e.message));
        // En cas d'erreur, on recharge depuis le serveur pour être cohérent
        await fetchDispos();
      }
    }
  };

  const inp = {
    background: 'var(--surface2)',
    border: '1px solid var(--border)',
    borderRadius: 10,
    color: 'var(--text)',
    padding: '10px 14px',
    fontSize: '.9rem',
    outline: 'none',
    width: '100%',
    boxSizing: 'border-box',
  };

  if (loading) {
    return <div style={{ padding: 50, textAlign: 'center' }}>Chargement...</div>;
  }

  return (
    <div style={{ padding: 32, maxWidth: 1000, margin: '0 auto' }}>
      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 30 }}>
        <h2 style={{ fontFamily: 'Syne', margin: 0 }}>🗓 Mes disponibilités</h2>
        <button
          onClick={() => setShowForm(true)}
          style={{
            background: 'var(--accent)',
            color: '#fff',
            border: 'none',
            padding: '12px 20px',
            borderRadius: 12,
            fontWeight: 600,
            cursor: 'pointer',
          }}
        >
          + Créer une séance
        </button>
      </div>

      {/* GRILLE PRINCIPALE */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: 30 }}>
        {/* LISTE DES SÉANCES */}
        <div
          style={{
            background: 'var(--card)',
            border: '1px solid var(--border)',
            borderRadius: 20,
            padding: 24,
          }}
        >
          <h3 style={{ marginBottom: 20, marginTop: 0 }}>📅 Séances planifiées</h3>

          {dispos.length === 0 && (
            <p style={{ color: 'var(--text2)' }}>Aucun créneau enregistré.</p>
          )}

          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {dispos.map(d => (
              <div
                key={d.id}
                style={{
                  background: 'var(--surface2)',
                  padding: 16,
                  borderRadius: 15,
                  border: '1px solid var(--border)',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}
              >
                <div>
                  <div style={{ fontWeight: 700, color: 'var(--accent)' }}>{d.date_specifique}</div>
                  <div style={{ fontSize: '.85rem' }}>
                    🕒 {d.heure_debut.slice(0, 5)} - {d.heure_fin.slice(0, 5)}
                  </div>
                  <div style={{ fontSize: '.8rem', marginTop: 4, color: 'var(--text2)' }}>
                    👥 Capacité : {d.nb_inscrits} / {d.nb_max_etudiants}
                  </div>
                </div>
                <button
                  onClick={() => handleDelete(d.id)}
                  style={{
                    background: 'rgba(255,101,132,0.1)',
                    color: '#ff6584',
                    border: 'none',
                    padding: '8px',
                    borderRadius: 8,
                    cursor: 'pointer',
                    fontSize: '1rem',
                  }}
                >
                  🗑
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* CALENDRIER */}
        <div
          style={{
            background: 'var(--card)',
            border: '1px solid var(--border)',
            borderRadius: 20,
            padding: 24,
          }}
        >
          <h3 style={{ marginBottom: 20, marginTop: 0 }}>👀 Calendrier</h3>
          <Calendar available={dispos.map(d => new Date(d.date_specifique).getDate())} />
        </div>
      </div>

      {/* MODAL AJOUT CRÉNEAU */}
      {showForm && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.85)',
            zIndex: 2000,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <div
            style={{
              background: 'var(--surface)',
              padding: 32,
              borderRadius: 24,
              width: 400,
              border: '1px solid var(--border)',
            }}
          >
            <h3 style={{ marginTop: 0, marginBottom: 20 }}>Nouveau créneau</h3>

            <form onSubmit={handleAdd} style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
              <input
                type="date"
                style={inp}
                required
                value={newDispo.date_specifique}
                onChange={e => setNewDispo({ ...newDispo, date_specifique: e.target.value })}
              />

              <div style={{ display: 'flex', gap: 10 }}>
                <input
                  type="time"
                  style={inp}
                  required
                  value={newDispo.heure_debut}
                  onChange={e => setNewDispo({ ...newDispo, heure_debut: e.target.value })}
                />
                <input
                  type="time"
                  style={inp}
                  required
                  value={newDispo.heure_fin}
                  onChange={e => setNewDispo({ ...newDispo, heure_fin: e.target.value })}
                />
              </div>

              <input
                type="number"
                min="1"
                style={inp}
                placeholder="Nombre max étudiants"
                value={newDispo.nb_max_etudiants}
                onChange={e => setNewDispo({ ...newDispo, nb_max_etudiants: e.target.value })}
              />

              <div style={{ display: 'flex', gap: 10, marginTop: 10 }}>
                <button
                  type="submit"
                  disabled={submitting}
                  style={{
                    flex: 2,
                    background: submitting ? 'var(--border)' : 'var(--accent)',
                    color: '#fff',
                    border: 'none',
                    padding: 12,
                    borderRadius: 12,
                    fontWeight: 700,
                    cursor: submitting ? 'not-allowed' : 'pointer',
                  }}
                >
                  {submitting ? 'Envoi...' : 'Planifier'}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowForm(false);
                    setNewDispo({ ...EMPTY_DISPO });
                  }}
                  style={{
                    flex: 1,
                    background: 'var(--surface2)',
                    color: '#fff',
                    border: 'none',
                    padding: 12,
                    borderRadius: 12,
                    cursor: 'pointer',
                  }}
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
